/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Visual Poetry".

Sealed.
Breath bought and rationed.
Shift! Only for those who can afford it.
Still for the many.
Sealed.
Breath priced.
Shift sold.
No open.

I wanted to experiment with subsurface scattering a bit and thought
this image would be suitable for the current challenge.
*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, moves=[0,0];

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return
	moves[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * scale
	moves[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * scale
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2730070/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
  createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
  resizeCanvas(windowWidth, windowHeight)
}

function draw() {
	mouseMove();
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
	theShader.setUniform("move", moves)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
#define N normalize
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
float noise(vec2 p) {
	vec2 f=fract(p), i=floor(p), u=f*f*(3.-2.*f);
	float
	a=rnd(i),
	b=rnd(i+vec2(1,0)),
	c=rnd(i+vec2(0,1)),
	d=rnd(i+vec2(1,1));
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float segment(vec3 p, vec2 s) {
	p.x-=clamp(p.x,-s.x/2.,s.x/2.);
	return length(p)-s.y;
}
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
float upperlip(vec3 p) {
	p.yz*=rot(.7-sin(T)*.02);
	p.y-=.3*sin(6.5*smin(p.x,-p.x,-.6-.02*sin(T)));
	float a=.75*noise(abs(p.xz)), f=noise(vec2(1,a));
	f+=noise(vec2(6.*a,22.*a));	
	float d=segment(p-vec3(0,0,.08),vec2(1,.25-.2*sin(smin(p.x,-p.x,-.9)-.0125*sin(noise(f*abs(p.xy)*-222.)))));
	d-=.00035*sin(p.y-p.x*(422.-50.*noise(2.-p.yy*12.)));
	return d;
}
float lowerlip(vec3 p) {
	p.yz*=rot(-.2-.02*sin(T));
	p.y+=.42*cos(smin(p.x,-p.x,1.5)*1.5)-.32;
	p.y-=.1*sin(smin(p.x,-p.x,-.8));
	float a=.75*noise(abs(p.xz)), f=noise(vec2(1,a));
	f+=noise(vec2(6,22.*a));
	float d=segment(p,vec2(1,.25-.2*sin(smin(p.x,-p.x,-.5)*1.2-.0125*sin(noise(abs(f*p.yx+1.)*-222.)))));
	d-=.00035*sin(p.x*(422.-50.*noise(9.+p.yy*12.)));
	return d;
}
float map(vec3 p) {
	p.y+=.1;
	return .8*smin(
		smin(smin(smin(upperlip(p),lowerlip(p),.002),-(-p.z),-.1),-(p.yz*rot(3.6)).y,-.1),
		length(p-vec3(0,0,-.32))-.5,
		-.1
	);
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1)*.5773;
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
float getsss(vec3 p, vec3 rd, float dist, float k) {
	if (dist<5e-5) return .0;
  float ddist=dist*k;
  return
  	clamp(map(p+rd*dist)/dist,.0,1.)+
  	clamp(map(p+rd*ddist)/ddist,.0,1.);
}
void cam(inout vec3 p) {
	p.yz*=rot(-move.y*6.3/MN-.78);
	p.xz*=rot(.42-move.x*6.3/MN);
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,-1),
	rd=N(vec3(uv,.7));
	cam(p); cam(rd);
	float dd=.0;
	for (int i; i++<200;) {
		float d=map(p);
		if (abs(d)<1e-3 || dd>100.) break;
		dd+=d;
		p+=rd*d;
	}
	vec3 mat=vec3(3,1,.9)/2., n=norm(p), lp=vec3(7,0,-1.5), l=N(lp-p);
	float dif=clamp(dot(l,n),.0,1.),
	spec=pow(clamp(dot(reflect(rd,n),l),.0,1.),32.);
	float steps=10., sss=.0, k=mix(.8,1.,rnd(rd.xy+T));
	for (float i=.0; i<steps; i++) {
		float dist=i/steps*k;
		sss+=getsss(p,N(lp),dist,.6);
	}
	if (dd<2.)  {
		sss*=.08;
		col+=mat*.2+mat*sss;
		col+=.2*mat+.1*dif*mat+.1*dif;
		col+=.5*spec*mat+.75*spec;
		col/=1.+exp(-col*col);
		col=sqrt(col);
		col*=.8;
	} else {
		col=vec3(1,.6,.4);
		col/=1.+exp(-col);
		col=sqrt(col);
	}
	uv=.6*(FC/R*2.-1.);
	col=mix(col,mat*.1,pow(dot(uv,uv),1.2));
	O=vec4(col,1);
}

